exec(open('actions-lib.py').read())
wait()
J=lambda v: json.dumps(v)
OPEN="(async()=>{const e=document.querySelector('[role=combobox][aria-label=Example]');const r=e.getBoundingClientRect();return JSON.stringify([r.x+r.width/2,r.y+r.height/2])})()"
def OPT(n): return "(async()=>{const e=await window.__h.until(()=>[...document.querySelectorAll('[role=option]')].find(e=>e.innerText.trim()===%s),8000,'option %s');const r=e.getBoundingClientRect();return JSON.stringify([r.x+r.width/2,r.y+r.height/2])})()"%(J(n),n)
LABEL="document.querySelector('[role=combobox][aria-label=Example]').innerText.trim()"
DOC="window.__doc=async()=>{const h=window.__h;if(!h.find('Add Step…'))await h.actions();const s=h.steps();if(!h.labels().length||!document.querySelector('[data-slot=tree-label]')){h.click('Artifact');await h.wait(800)}return {steps:s,rows:h.labels(),picker:"+LABEL+"}};"
def doc_until(pred, what, ms=420000): return "(async()=>{try{const d=await window.__doc();return String(!/Loading document/.test(document.body.innerText)&&(%s))}catch(e){return 'false'}})()"%pred
STOCK={"Cylinder":0.2827,"Sphere":0.5236,"Box":1.0}
step("D0 demo document loaded: Timber Beam stock with 4 steps","await h.actions();await h.stepsNow(s=>s.n===4,150000,'demo steps');"+DOC+"h.click('Artifact');await h.until(()=>h.find('Cut Lap Joint'),30000,'rows');const d=await window.__doc();h.ok(d.rows.includes('Timber Beam')&&Math.abs(d.steps.vol-0.174)<1e-3,'demo '+h.json(d));return h.json(d)",timeoutMs=170000,capture=True,minCanvasPixels=200)
for kind,vol in STOCK.items():
    step("D1 Set Stock %s replaces the stock and resets the timeline"%kind,"await h.form('Set Stock…');await h.pick(%s);await h.exec();const s=await h.stepsNow(s=>s.n===0&&Math.abs(s.vol-%f)/%f<0.03,120000,'%s stock with 0 steps and %.4f m³');h.click('Artifact');await h.wait(800);const rows=h.labels();h.ok(!rows.includes('Cut Lap Joint')&&!rows.includes('Drill Dowel Hole'),'old steps remain '+h.json(rows));return h.json({s,rows})"%(J(kind),vol,vol,kind,vol),timeoutMs=170000,capture=True,minCanvasPixels=200)
step("D2 Set Stock keeps the installed workshop","h.click('Workshop');await h.until(()=>h.find('Table Saw'),30000,'workshop');const l=h.labels();for(const m of ['Generic Saw','Table Saw','CNC Router'])h.ok(l.includes(m),'workshop kept '+m+' '+h.json(l));h.click('Artifact');return h.json(l)")
step("D3 Set Active Example offers the registered examples","await h.form('Set Active Example…');const boxes=[...document.querySelectorAll('[role=combobox]')].filter(b=>b.getAttribute('aria-label')!=='Example');boxes[boxes.length-1].click();await h.wait(800);const opts=[...document.querySelectorAll('[role=option]')].map(e=>e.innerText.trim());document.activeElement&&document.activeElement.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));await h.wait(500);for(const o of ['Timber Beam Joinery','Drilled Plate','Concrete Forest'])h.ok(opts.includes(o),'option '+o+' in '+h.json(opts));return h.json(opts)")
step("D4 Set Active Example Drilled Plate loads the plate document","await h.form('Set Active Example…');await h.pick('Drilled Plate');await h.exec();return 'requested'")
step("D5 plate document is active: Plate stock with 4 steps","const d=await window.__doc();h.ok(d.rows.includes('Plate')&&!d.rows.includes('Timber Beam')&&d.steps.n===4,'plate '+h.json(d));window.__plate=d.steps;return h.json(d)",until=doc_until("d.steps&&d.steps.n===4&&d.rows.includes('Plate')","plate"),timeoutMs=420000,capture=True,minCanvasPixels=200)
step("D6 Set Active Example Timber Beam Joinery loads the demo document","await h.form('Set Active Example…');await h.pick('Timber Beam Joinery');await h.exec();return 'requested'")
step("D7 timber document is active: Timber Beam stock, 4 steps, 0.1740 m³","const d=await window.__doc();h.ok(d.rows.includes('Timber Beam')&&d.rows.includes('Cut Lap Joint')&&Math.abs(d.steps.vol-0.174)<1e-3,'timber '+h.json(d));return h.json(d)",until=doc_until("d.steps&&d.steps.n===4&&Math.abs(d.steps.vol-0.174)<1e-3&&d.rows.includes('Timber Beam')","timber"),timeoutMs=420000,capture=True,minCanvasPixels=200)
step("D8 Set Active Example Concrete Forest loads the forest document","await h.form('Set Active Example…');await h.pick('Concrete Forest');await h.exec();return 'requested'")
step("D9 forest document is active: forest stock with 7 steps","const d=await window.__doc();h.ok(d.rows.includes('Hexagonal Cut Concrete Forest Left')&&d.steps.n===7,'forest '+h.json(d));return h.json(d)",until=doc_until("d.steps&&d.steps.n===7&&d.rows.includes('Hexagonal Cut Concrete Forest Left')","forest"),timeoutMs=420000,capture=True,minCanvasPixels=200)
step("D10 navbar picker opens","return 'o'",pointer=OPEN,settleMs=1000)
step("D11 navbar picker Demo","return 'p'",pointer=OPT('Demo'),settleMs=1000)
step("D12 navbar Demo loads the timber document","const d=await window.__doc();h.ok(d.picker==='Demo'&&d.rows.includes('Timber Beam')&&d.steps.n===4&&Math.abs(d.steps.vol-0.174)<1e-3,'demo '+h.json(d));return h.json(d)",until=doc_until("d.picker==='Demo'&&d.steps&&d.steps.n===4&&Math.abs(d.steps.vol-0.174)<1e-3&&d.rows.includes('Timber Beam')","demo"),timeoutMs=420000,capture=True,minCanvasPixels=200)
step("D13 navbar picker opens","return 'o'",pointer=OPEN,settleMs=1000)
step("D14 navbar picker Concrete Forest","return 'p'",pointer=OPT('Concrete Forest'),settleMs=1000)
step("D15 navbar Concrete Forest loads the forest document","const d=await window.__doc();h.ok(d.picker==='Concrete Forest'&&d.rows.includes('Hexagonal Cut Concrete Forest Left')&&d.steps.n===7,'forest '+h.json(d));return h.json(d)",until=doc_until("d.picker==='Concrete Forest'&&d.steps&&d.steps.n===7&&d.rows.includes('Hexagonal Cut Concrete Forest Left')","forest"),timeoutMs=420000,capture=True,minCanvasPixels=200)
step("D16 navbar picker opens","return 'o'",pointer=OPEN,settleMs=1000)
step("D17 navbar picker No example","return 'p'",pointer=OPT('No example'),settleMs=1000)
step("D18 No example clears the active document to the empty default document","const d=await window.__doc();h.ok(d.picker==='No example','picker '+d.picker);h.ok(!d.rows.includes('Hexagonal Cut Concrete Forest Left')&&!d.rows.includes('Timber Beam')&&!d.rows.includes('Plate'),'old stock still present '+h.json(d));h.ok(!d.steps||(d.steps.n===0),'steps remain '+h.json(d.steps));return h.json(d)",until=doc_until("d.picker==='No example'&&(!d.steps||d.steps.n===0)&&!d.rows.includes('Hexagonal Cut Concrete Forest Left')","empty"),timeoutMs=420000,capture=True)
step("D19 the app stays usable after clearing: Demo loads again","return 'o'",pointer=OPEN,settleMs=1000)
step("D20 navbar picker Demo","return 'p'",pointer=OPT('Demo'),settleMs=1000)
step("D21 Demo document is back","const d=await window.__doc();h.ok(d.picker==='Demo'&&d.steps.n===4&&d.rows.includes('Timber Beam'),'demo '+h.json(d));return h.json(d)",until=doc_until("d.picker==='Demo'&&d.steps&&d.steps.n===4&&d.rows.includes('Timber Beam')","demo again"),timeoutMs=420000,capture=True,minCanvasPixels=200)
save("process-actions-docs.json")
